SELECT CASE WHEN s.rating >= 4.5 THEN 'high' WHEN s.rating >= 2.4 THEN 'mid' ELSE 'low' END AS rating_bucket, COUNT(DISTINCT ss.revenue) AS unique_stores, COUNT(ss.revenue) AS revenue_count FROM store_sales ss LEFT JOIN products p ON ss.product_id = p.id INNER JOIN suppliers s ON p.supplier_id = s.id GROUP BY CASE WHEN s.rating >= 4.5 THEN 'high' WHEN s.rating >= 2.4 THEN 'mid' ELSE 'low' END;
